namespace sv_7dffb929f68f4935934bb4a9325d50d9.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Brown",
        "Dr. Davis"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:30 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Brown"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
        ["Dr. Davis"] = ["9:00 AM", "11:00 AM", "1:30 PM", "4:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(new List<string>(slots));
        }

        return Task.FromResult(new List<string>());
    }

    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_7dffb929f68f4935934bb4a9325d50d9.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ── STEP 1 ── *@
    <div class="card mb-4">
        <div class="card-header"><strong>Step 1 – Patient Information</strong></div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="Model.PatientName" />
                <ValidationMessage For="() => Model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
                @if (serverErrors.ContainsKey("Email"))
                {
                    <div class="validation-message">@serverErrors["Email"]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>
        </div>
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next &rarr;
        </button>
    }

    @* ── STEP 2 ── *@
    @if (showStep2)
    {
        <div class="card mb-4">
            <div class="card-header"><strong>Step 2 – Appointment Details</strong></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-select" @bind-Value="Model.Doctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.Doctor" />
                    @if (serverErrors.ContainsKey("Doctor"))
                    {
                        <div class="validation-message">@serverErrors["Doctor"]</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="Model.AppointmentDate"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                    @if (serverErrors.ContainsKey("TimeSlot"))
                    {
                        <div class="validation-message">@serverErrors["TimeSlot"]</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" rows="3" @bind-Value="Model.Reason" />
                    <ValidationMessage For="() => Model.Reason" />
                </div>
            </div>
        </div>

        <div class="d-flex gap-2">
            <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                &larr; Back
            </button>
            <button type="button" class="btn btn-info" @onclick="CheckAvailability"
                    disabled="@isChecking">
                @(isChecking ? "Checking…" : "Check Availability")
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                Book Appointment
            </button>
        </div>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();

    private bool showStep2;
    private bool isChecking;
    private bool availabilityChecked;
    private bool booked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var isValid = editContext.Validate();

        // Only need step-1 fields valid to proceed
        var messages = editContext.GetValidationMessages();
        var step1Props = new[] { nameof(Model.PatientName), nameof(Model.Email),
                                 nameof(Model.Phone), nameof(Model.InsuranceProvider) };
        var step1Errors = editContext.GetValidationMessages()
            .Where((_, i) =>
            {
                // DataAnnotationsValidator puts messages on FieldIdentifier
                return true;
            });

        // Re-check only step 1 fields
        var hasStep1Error = step1Props.Any(p =>
            editContext.GetValidationMessages(editContext.Field(p)).Any());

        if (!hasStep1Error)
        {
            showStep2 = true;
            _ = LoadDoctorsAsync();
        }
    }

    private async Task LoadDoctorsAsync()
    {
        doctors = await AppointmentSvc.GetDoctorsAsync();
        StateHasChanged();
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            var date = DateOnly.FromDateTime(Model.AppointmentDate.Value);
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(Model.Doctor, date);
            Model.TimeSlot = string.Empty;
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        editContext = new EditContext(Model);
        editContext.Validate();

        var step2Props = new[] { nameof(Model.Doctor), nameof(Model.AppointmentDate),
                                 nameof(Model.TimeSlot), nameof(Model.Reason) };
        var hasStep2Error = step2Props.Any(p =>
            editContext.GetValidationMessages(editContext.Field(p)).Any());

        if (hasStep2Error)
        {
            return;
        }

        isChecking = true;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        isChecking = false;

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        availabilityChecked = false;
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            booked = true;
        }
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_7dffb929f68f4935934bb4a9325d50d9.Models;

public class AppointmentModel : IValidatableObject
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Invalid phone number.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2 fields — validated only when step 2 is active

    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Appointment date is required.")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string Reason { get; set; } = string.Empty;

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        if (AppointmentDate.HasValue && AppointmentDate.Value.Date <= DateTime.Today)
        {
            yield return new ValidationResult(
                "Appointment date must be in the future.",
                [nameof(AppointmentDate)]);
        }
    }
}

