    {
        serverErrors.Clear();
        availabilityChecked = false;

        editContext = new EditContext(Model);
        editContext.Validate();

        var step2Props = new[] { nameof(Model.Doctor), nameof(Model.AppointmentDate),
                                 nameof(Model.TimeSlot), nameof(Model.Reason) };
        var hasStep2Error = step2Props.Any(p =>
            editContext.GetValidationMessages(editContext.Field(p)).Any());

        if (hasStep2Error)
        {
            return;
        }

        isChecking = true;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        isChecking = false;

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
        availabilityChecked = false;
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            booked = true;
        }
    }
}
"}

